{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "A pergunta é a maior arrecadação possível. Arrecadação é preço vezes quantidade vendida, e os dois mudam juntos: se o preço cai, vendem-se mais combos. Chame de x o número de reduções de R$ 1,00. Preço e quantidade viram expressões em x, e o produto desenha uma parábola aberta para baixo, que tem um ponto mais alto (o máximo).",
      "motivo": "Começa pelo comando e usa palavras mais simples; troca 'receita' por 'arrecadação', que é o termo da questão."
    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "arrecadação = preço × quantidade",
        "x do vértice = −b ÷ (2a)",
        "valor máximo = arrecadação calculada nesse x"
      ],
      "motivo": "Fração escrita como se diz em aula; mantém o mesmo termo do enunciado."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["x", "número de reduções de R$ 1,00 aplicadas ao preço do combo"],
        ["R(x)", "arrecadação diária em reais, que depende de x"],
        ["parábola", "curva em forma de 'U'. Aqui ela abre para baixo, como um morro"],
        ["vértice", "ponto mais alto da parábola quando ela abre para baixo: é onde a arrecadação é máxima"],
        ["a, b, c", "números que multiplicam x², x e o termo sozinho em R(x) = ax² + bx + c"]
      ],
      "motivo": "Explica 'parábola' e inclui o c, que aparece na forma geral."
    },
    {
      "campo": "resolucao.passos[2].porque",
      "depois": "Arrecadação é preço vezes quantidade. Multiplicando cada termo: 2000 + 1000x − 200x − 100x². Juntando 1000x − 200x = 800x, fica R = −100x² + 800x + 2000.",
      "motivo": "Frase mais clara, sem 'isto é', mostrando a soma dos termos em x."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "x = −800 ÷ (2 × (−100))",
      "motivo": "Cabe na tela do celular e é lida como divisão no caderno."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "Como a = −100 é negativo, a parábola abre para baixo, e o ponto mais alto é o vértice. Então x = −b ÷ (2a) = −800 ÷ (−200) = 4.",
      "motivo": "Mostra a divisão final que faltava e liga o sinal de a ao máximo."
    },
    {
      "campo": "resolucao.passos[4].conta",
      "depois": "R(4) = 6 × 600 = 3600",
      "motivo": "Sem mudança de valor; mantém a conta visível."
    },
    {
      "campo": "resolucao.checagem",
      "depois": "Teste os vizinhos de x = 4. Com x = 3: 7 × 500 = 3500. Com x = 5: 5 × 700 = 3500. Os dois são menores que 3600, então 3600 é o máximo. Outra checagem: R zera em x = 10 e x = −2, e o vértice fica no meio: (10 − 2) ÷ 2 = 4.",
      "motivo": "Frase mais simples; explica que R zera nas raízes."
    },
    {
      "campo": "resolucao.erradas.D",
      "depois": "R$ 4.000,00 não confere: a arrecadação nunca chega a esse valor. R = 4000 daria −100x² + 800x + 2000 = 4000, ou seja, x² − 8x + 20 = 0. Aqui b² − 4ac = 64 − 80 = −16, negativo, e não existe x real. O máximo é 3600.",
      "motivo": "A equação do texto original estava incoerente (faltava o fator 100); agora parte de R = 4000 e chega ao mesmo discriminante."
    },
    {
      "campo": "resolucao.erradas.E",
      "depois": "R$ 4.800,00 não confere: R = 4800 daria −100x² + 800x + 2000 = 4800, ou seja, x² − 8x + 28 = 0. Aqui b² − 4ac = 64 − 112 = −48, negativo, e não existe x real. Esse valor está acima do máximo de 3600.",
      "motivo": "Mesma correção de clareza da alternativa D."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
